CREATE OR REPLACE FUNCTION private.admin_adjust_wallet(p_user_id uuid, p_currency text, p_direction text, p_amount numeric, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_admin uuid := auth.uid();
  v_currency text := upper(btrim(p_currency));
  v_direction text := lower(btrim(p_direction));
  v_reason text := btrim(p_reason);
  v_before numeric;
  v_after numeric;
  v_reserved numeric := 0;
  v_delta numeric;
  v_storage_delta numeric;
begin
  if v_admin is null or not private.is_super_admin() then
    raise exception 'Super administrator access required' using errcode = '42501';
  end if;
  if p_user_id is null or not exists (select 1 from public.profiles p where p.id = p_user_id) then
    raise exception 'Target account not found';
  end if;
  if v_currency not in ('USDT','TOMAN') then
    raise exception 'Currency must be USDT or TOMAN';
  end if;
  if v_direction not in ('credit','debit') then
    raise exception 'Direction must be credit or debit';
  end if;
  if p_amount is null or p_amount <= 0 or p_amount > 1000000000000 then
    raise exception 'Invalid adjustment amount';
  end if;
  if v_reason is null or char_length(v_reason) < 5 or char_length(v_reason) > 500 then
    raise exception 'Reason must contain 5 to 500 characters';
  end if;

  insert into public.wallets(user_id) values (p_user_id)
  on conflict (user_id) do nothing;
  select case when v_currency = 'USDT' then w.balance_usdt else w.balance_irr / 10 end
  into v_before from public.wallets w where w.user_id = p_user_id for update;

  v_delta := case when v_direction = 'credit' then p_amount else -p_amount end;
  v_storage_delta := case when v_currency = 'TOMAN' then v_delta * 10 else v_delta end;
  if v_currency = 'USDT' and v_direction = 'debit' then
    select coalesce(sum(greatest(r.reserved_amount-r.consumed_amount-r.released_amount,0)),0)
    into v_reserved from public.order_reservations r
    where r.user_id = p_user_id and r.asset = 'USDT' and r.status = 'reserved';
    if v_before - v_reserved < p_amount then
      raise exception 'Insufficient available USDT; funds reserved by open orders cannot be withdrawn';
    end if;
  elsif v_direction = 'debit' and v_before < p_amount then
    raise exception 'Insufficient wallet balance';
  end if;

  v_after := v_before + v_delta;
  if v_currency = 'USDT' then
    update public.wallets set balance_usdt = v_after where user_id = p_user_id;
  else
    update public.wallets set balance_irr = v_after * 10 where user_id = p_user_id;
  end if;
  insert into public.transactions(user_id,currency,amount,transaction_type,description)
  values (p_user_id,case when v_currency='TOMAN' then 'IRR' else 'USDT' end,v_storage_delta,'admin_adjustment','مدیریت اعتبار آزمایشی: ' || v_reason);
  insert into private.admin_wallet_adjustments(admin_user_id,target_user_id,currency,direction,amount,balance_before,balance_after,reason)
  values (v_admin,p_user_id,v_currency,v_direction,p_amount,v_before,v_after,v_reason);
  return jsonb_build_object('success',true,'user_id',p_user_id,'currency',v_currency,'direction',v_direction,'amount',p_amount,'balance_before',v_before,'balance_after',v_after);
end;
$function$

CREATE OR REPLACE FUNCTION private.enforce_unique_admin_market_listing_symbol()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_symbol text;
BEGIN
  SELECT ca.symbol INTO v_symbol
  FROM public.crypto_assets ca
  WHERE ca.coingecko_id = NEW.coingecko_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Curated asset does not exist';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.admin_market_listings l
    JOIN public.crypto_assets other ON other.coingecko_id = l.coingecko_id
    WHERE l.coingecko_id <> NEW.coingecko_id
      AND pg_catalog.upper(other.symbol) = pg_catalog.upper(v_symbol)
  ) THEN
    RAISE EXCEPTION 'Another curated asset already uses this ticker';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.demo_trading_pairs dp
    WHERE dp.pair_symbol = pg_catalog.upper(v_symbol) || 'USDT'
      AND dp.base_coingecko_id <> NEW.coingecko_id
  ) THEN
    RAISE EXCEPTION 'Ticker conflicts with an existing demo trading pair';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION private.guard_active_account_writes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_active boolean;
begin
  select p.is_active into v_active
  from public.profiles p
  where p.id = new.user_id
  for share;

  if coalesce(v_active, false) is not true then
    raise exception 'Account is inactive; reactivate the account before trading';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.request_market_price_overflow()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_overflow_ids text[];
  v_total integer;
  v_offset integer;
  v_end integer;
  v_ids text;
  v_request_id bigint;
  v_requests integer := 0;
BEGIN
  -- Keep overflow scheduling separate from the primary price-refresh lock.
  IF NOT pg_catalog.pg_try_advisory_xact_lock(742019, 14) THEN
    RETURN 0;
  END IF;

  IF EXISTS (SELECT 1 FROM private.market_price_sync_requests)
     OR EXISTS (
       SELECT 1 FROM net.http_request_queue q
       WHERE q.url LIKE 'https://api.coingecko.com/api/v3/simple/price%'
     ) THEN
    RETURN 0;
  END IF;

  -- The primary refresh request already asks for the first 515 sorted IDs.
  -- Fetch every remaining ID in batches below CoinGecko's documented limit.
  SELECT ARRAY(
    SELECT all_ids.coingecko_id
    FROM (
      SELECT DISTINCT ids.coingecko_id
      FROM (
        SELECT dp.base_coingecko_id AS coingecko_id
        FROM public.demo_trading_pairs AS dp
        WHERE dp.is_enabled IS TRUE
        UNION
        SELECT ca.coingecko_id
        FROM public.admin_market_listings AS l
        JOIN public.crypto_assets AS ca ON ca.coingecko_id = l.coingecko_id
        WHERE ca.is_active IS TRUE
      ) AS ids
      WHERE ids.coingecko_id ~ '^[a-z0-9-]+$'
    ) AS all_ids
    ORDER BY all_ids.coingecko_id
    OFFSET 515
  )
  INTO v_overflow_ids;

  v_total := COALESCE(pg_catalog.array_length(v_overflow_ids, 1), 0);
  IF v_total = 0 THEN
    RETURN 0;
  END IF;

  FOR v_offset IN 1..v_total BY 500 LOOP
    v_end := LEAST(v_offset + 499, v_total);
    v_ids := pg_catalog.array_to_string(v_overflow_ids[v_offset:v_end], ',');

    v_request_id := net.http_get(
      url := 'https://api.coingecko.com/api/v3/simple/price?ids='
        || v_ids || '&vs_currencies=usd',
      timeout_milliseconds := 20000
    );

    INSERT INTO private.market_price_sync_requests(request_id)
    VALUES (v_request_id)
    ON CONFLICT DO NOTHING;

    v_requests := v_requests + 1;
  END LOOP;

  RETURN v_requests;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_add_market_listing(p_coingecko_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_admin uuid := auth.uid();
  v_asset public.crypto_assets%ROWTYPE;
  v_pair_symbol text;
BEGIN
  IF v_admin IS NULL OR NOT private.is_super_admin() THEN
    RAISE EXCEPTION 'Super administrator access required' USING errcode = '42501';
  END IF;

  IF p_coingecko_id IS NULL OR length(btrim(p_coingecko_id)) NOT BETWEEN 1 AND 128 THEN
    RAISE EXCEPTION 'Invalid CoinGecko asset id';
  END IF;

  SELECT *
  INTO v_asset
  FROM public.crypto_assets
  WHERE coingecko_id = btrim(p_coingecko_id)
    AND is_active IS TRUE
    AND current_price_usd > 0
    AND last_updated >= now() - interval '24 hours';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Asset not found, inactive, or market data is stale';
  END IF;

  IF v_asset.symbol IS NULL OR v_asset.symbol !~ '^[A-Za-z0-9]{2,15}$'
     OR upper(v_asset.symbol) = 'USDT' THEN
    RAISE EXCEPTION 'Asset symbol is not valid for a USDT trading pair';
  END IF;

  v_pair_symbol := upper(v_asset.symbol) || 'USDT';

  IF EXISTS (
    SELECT 1
    FROM public.demo_trading_pairs
    WHERE pair_symbol = v_pair_symbol
      AND base_coingecko_id <> v_asset.coingecko_id
  ) THEN
    RAISE EXCEPTION 'Trading-pair symbol conflicts with another asset';
  END IF;

  -- An existing pair for this same CoinGecko asset is valid and must not
  -- prevent adding the asset to the admin-curated list. Pair creation or
  -- reactivation remains the responsibility of admin_enable_market_pair().
  INSERT INTO public.admin_market_listings(coingecko_id, added_by)
  VALUES (v_asset.coingecko_id, v_admin)
  ON CONFLICT (coingecko_id) DO NOTHING;

  RETURN jsonb_build_object(
    'success', true,
    'coingecko_id', v_asset.coingecko_id,
    'symbol', v_asset.symbol,
    'name', v_asset.name,
    'pair_symbol', v_pair_symbol,
    'pair_already_exists', EXISTS (
      SELECT 1
      FROM public.demo_trading_pairs
      WHERE pair_symbol = v_pair_symbol
        AND base_coingecko_id = v_asset.coingecko_id
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_disable_market_pair(p_coingecko_id text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_admin uuid := auth.uid();
  v_pair public.demo_trading_pairs%ROWTYPE;
  v_cancelled integer := 0;
  v_released integer := 0;
BEGIN
  IF v_admin IS NULL OR NOT private.is_super_admin() THEN
    RAISE EXCEPTION 'Super administrator access required' USING errcode = '42501';
  END IF;
  IF p_coingecko_id IS NULL THEN
    RAISE EXCEPTION 'CoinGecko asset id is required';
  END IF;

  SELECT * INTO v_pair
  FROM public.demo_trading_pairs
  WHERE base_coingecko_id = pg_catalog.btrim(p_coingecko_id)
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Trading pair not found';
  END IF;

  -- Cancel all outstanding conditional exits first so the worker cannot
  -- execute a trigger after the pair has been disabled.
  UPDATE public.conditional_orders AS co
  SET status = 'cancelled',
      last_error = 'Pair disabled by administrator',
      updated_at = now()
  FROM public.orders AS o
  WHERE co.order_id = o.id
    AND o.symbol = v_pair.pair_symbol
    AND o.order_type = 'conditional'
    AND o.status IN ('pending','partially_filled')
    AND co.status = 'pending';

  UPDATE public.order_reservations AS r
  SET released_amount = r.reserved_amount - r.consumed_amount,
      status = CASE WHEN r.consumed_amount >= r.reserved_amount THEN 'consumed' ELSE 'released' END,
      updated_at = now()
  FROM public.orders AS o
  WHERE r.order_id = o.id
    AND o.symbol = v_pair.pair_symbol
    AND o.order_type IN ('limit','conditional')
    AND o.status IN ('pending','partially_filled')
    AND r.status = 'reserved';

  GET DIAGNOSTICS v_released = ROW_COUNT;

  UPDATE public.orders
  SET status = 'cancelled',
      remaining_amount = amount - filled_amount
  WHERE symbol = v_pair.pair_symbol
    AND order_type IN ('limit','conditional')
    AND status IN ('pending','partially_filled');

  GET DIAGNOSTICS v_cancelled = ROW_COUNT;

  UPDATE public.demo_trading_pairs
  SET is_enabled = false, updated_at = now()
  WHERE pair_symbol = v_pair.pair_symbol;

  INSERT INTO private.market_pair_admin_audit(
    pair_symbol, coingecko_id, action, admin_user_id, reason, validation_snapshot
  )
  VALUES(v_pair.pair_symbol, v_pair.base_coingecko_id, 'disabled', v_admin,
         pg_catalog.left(COALESCE(p_reason, 'Disabled by super administrator'), 500),
         pg_catalog.jsonb_build_object(
           'cancelled_open_orders', v_cancelled,
           'reservations_released', v_released
         ));

  RETURN pg_catalog.jsonb_build_object(
    'success', true,
    'pair_symbol', v_pair.pair_symbol,
    'status', 'disabled',
    'cancelled_open_orders', v_cancelled,
    'reservations_released', v_released
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_enable_market_pair(p_coingecko_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_admin uuid := auth.uid();
  v_asset public.crypto_assets%ROWTYPE;
  v_pair_symbol text;
  v_price numeric;
  v_price_source text;
  v_price_updated_at timestamptz;
  v_validation jsonb;
  v_rows integer;
BEGIN
  IF v_admin IS NULL OR NOT private.is_super_admin() THEN
    RAISE EXCEPTION 'Super administrator access required' USING errcode = '42501';
  END IF;
  IF p_coingecko_id IS NULL OR pg_catalog.length(pg_catalog.btrim(p_coingecko_id)) NOT BETWEEN 1 AND 128 THEN
    RAISE EXCEPTION 'Invalid CoinGecko asset id';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext('digiarz-pair:' || p_coingecko_id));

  SELECT ca.* INTO v_asset
  FROM public.crypto_assets AS ca
  JOIN public.admin_market_listings AS l ON l.coingecko_id = ca.coingecko_id
  WHERE ca.coingecko_id = pg_catalog.btrim(p_coingecko_id)
  FOR SHARE OF ca;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Asset must first be added to the admin-curated market list';
  END IF;
  IF v_asset.is_active IS NOT TRUE
     OR v_asset.current_price_usd IS NULL OR v_asset.current_price_usd <= 0
     OR v_asset.last_updated IS NULL OR v_asset.last_updated < now() - interval '24 hours'
     OR v_asset.total_volume_usd IS NULL OR v_asset.total_volume_usd < 1000000
     OR (v_asset.market_cap_rank IS NOT NULL AND v_asset.market_cap_rank > 2000) THEN
    RAISE EXCEPTION 'Asset does not meet the current market-data and liquidity requirements';
  END IF;

  IF v_asset.symbol !~ '^[A-Za-z0-9]{2,15}$'
     OR pg_catalog.upper(v_asset.symbol) = 'USDT' THEN
    RAISE EXCEPTION 'Asset symbol is not valid for a USDT trading pair';
  END IF;
  v_pair_symbol := pg_catalog.upper(v_asset.symbol) || 'USDT';

  IF EXISTS (
    SELECT 1 FROM public.demo_trading_pairs AS dp
    WHERE dp.pair_symbol = v_pair_symbol
      AND dp.base_coingecko_id <> v_asset.coingecko_id
  ) THEN
    RAISE EXCEPTION 'Trading-pair symbol conflicts with another asset';
  END IF;

  SELECT mp.price, mp.source, mp.updated_at
  INTO v_price, v_price_source, v_price_updated_at
  FROM public.market_prices AS mp
  WHERE mp.symbol = v_pair_symbol
  FOR SHARE;

  IF NOT FOUND OR v_price IS NULL OR v_price <= 0
     OR v_price_source <> 'CoinGecko'
     OR v_price_updated_at < now() - interval '2 minutes' THEN
    RAISE EXCEPTION 'A fresh CoinGecko price is required before enabling this pair';
  END IF;

  v_validation := pg_catalog.jsonb_build_object(
    'coingecko_id', v_asset.coingecko_id,
    'symbol', v_asset.symbol,
    'pair_symbol', v_pair_symbol,
    'price_usd', v_price,
    'price_source', v_price_source,
    'price_updated_at', v_price_updated_at,
    'metadata_updated_at', v_asset.last_updated,
    'volume_24h_usd', v_asset.total_volume_usd,
    'market_cap_rank', v_asset.market_cap_rank,
    'minimum_volume_24h_usd', 1000000,
    'maximum_metadata_age_hours', 24,
    'maximum_price_age_minutes', 2
  );

  INSERT INTO public.demo_trading_pairs(
    pair_symbol, base_coingecko_id, quote_asset, is_enabled, created_at, updated_at
  )
  VALUES(v_pair_symbol, v_asset.coingecko_id, 'USDT', true, now(), now())
  ON CONFLICT (pair_symbol) DO UPDATE
    SET is_enabled = true, updated_at = now()
    WHERE public.demo_trading_pairs.base_coingecko_id = EXCLUDED.base_coingecko_id;

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows <> 1 THEN
    RAISE EXCEPTION 'Trading pair could not be enabled because of a concurrent symbol conflict';
  END IF;

  INSERT INTO private.market_pair_admin_audit(
    pair_symbol, coingecko_id, action, admin_user_id, reason, validation_snapshot
  )
  VALUES(v_pair_symbol, v_asset.coingecko_id, 'enabled', v_admin,
         'Admin-approved activation after server-side eligibility checks', v_validation);

  RETURN pg_catalog.jsonb_build_object(
    'success', true,
    'pair_symbol', v_pair_symbol,
    'coingecko_id', v_asset.coingecko_id,
    'price_usd', v_price,
    'status', 'enabled',
    'validation', v_validation
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_remove_market_listing(p_coingecko_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_admin uuid := auth.uid();
  v_deleted integer;
BEGIN
  IF v_admin IS NULL OR NOT private.is_super_admin() THEN
    RAISE EXCEPTION 'Super administrator access required' USING errcode = '42501';
  END IF;
  DELETE FROM public.admin_market_listings
  WHERE coingecko_id = btrim(p_coingecko_id);
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN jsonb_build_object('success', true, 'removed', v_deleted > 0);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_request_exchange_asset_sync()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n_main integer; n_bit24 integer;
begin
  if not private.is_current_user_super_admin() then
    raise exception 'دسترسی مدیر ارشد لازم است' using errcode = '42501';
  end if;
  n_main := public.request_iran_exchange_asset_sync();
  n_bit24 := public.request_bit24_exchange_sync();
  return jsonb_build_object('requested_main', n_main, 'requested_bit24', n_bit24, 'requested_at', now());
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_conditional_exit_order(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_cond public.conditional_orders%ROWTYPE;
  v_res public.order_reservations%ROWTYPE;
  v_rows integer;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF NOT public.current_account_is_active() THEN RAISE EXCEPTION 'Account is inactive'; END IF;

  SELECT * INTO v_cond
  FROM public.conditional_orders
  WHERE order_id=p_order_id AND user_id=v_uid
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Conditional order not found'; END IF;
  IF v_cond.status <> 'pending' THEN RAISE EXCEPTION 'Conditional order cannot be cancelled'; END IF;

  SELECT * INTO v_res
  FROM public.order_reservations
  WHERE order_id=p_order_id AND user_id=v_uid
  FOR UPDATE;
  IF NOT FOUND OR v_res.status <> 'reserved'
     OR v_res.consumed_amount < 0
     OR v_res.consumed_amount+v_res.released_amount > v_res.reserved_amount THEN
    RAISE EXCEPTION 'Valid active reservation not found';
  END IF;

  UPDATE public.order_reservations
  SET released_amount=reserved_amount-consumed_amount,
      status=CASE WHEN consumed_amount>=reserved_amount THEN 'consumed' ELSE 'released' END,
      updated_at=now()
  WHERE id=v_res.id AND status='reserved';
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 THEN RAISE EXCEPTION 'Reservation release failed'; END IF;

  UPDATE public.orders
  SET status='cancelled',remaining_amount=amount-filled_amount
  WHERE id=p_order_id AND user_id=v_uid AND order_type='conditional'
    AND status IN ('pending','partially_filled');
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 THEN RAISE EXCEPTION 'Order cancellation failed'; END IF;

  UPDATE public.conditional_orders
  SET status='cancelled',updated_at=now()
  WHERE id=v_cond.id AND status='pending';
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 THEN RAISE EXCEPTION 'Conditional order cancellation failed'; END IF;

  RETURN jsonb_build_object('success',true,'status','cancelled','order_id',p_order_id,
    'released_amount',v_res.reserved_amount-v_res.consumed_amount);
END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_limit_order(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_uid uuid := auth.uid();
    v_order public.orders%ROWTYPE;
    v_rows integer;
BEGIN
    IF v_uid IS NULL THEN
        RAISE EXCEPTION 'Authentication required';
    END IF;

    SELECT *
    INTO v_order
    FROM public.orders
    WHERE id = p_order_id
      AND user_id = v_uid
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Order not found';
    END IF;

    IF v_order.order_type <> 'limit' THEN
        RAISE EXCEPTION 'Only limit orders can be cancelled here';
    END IF;

    IF v_order.status NOT IN ('pending', 'partially_filled') THEN
        RAISE EXCEPTION 'Order cannot be cancelled';
    END IF;

    UPDATE public.order_reservations
    SET released_amount = reserved_amount - consumed_amount,
        status = CASE
            WHEN consumed_amount >= reserved_amount THEN 'consumed'
            ELSE 'released'
        END,
        updated_at = now()
    WHERE order_id = p_order_id
      AND user_id = v_uid
      AND status = 'reserved'
      AND consumed_amount >= 0
      AND released_amount >= 0
      AND consumed_amount + released_amount <= reserved_amount;

    GET DIAGNOSTICS v_rows = ROW_COUNT;

    IF v_rows <> 1 THEN
        RAISE EXCEPTION
            'Cannot cancel order: exactly one valid active reservation is required';
    END IF;

    UPDATE public.orders
    SET status = 'cancelled',
        remaining_amount = amount - filled_amount
    WHERE id = p_order_id
      AND user_id = v_uid;

    GET DIAGNOSTICS v_rows = ROW_COUNT;

    IF v_rows <> 1 THEN
        RAISE EXCEPTION 'Order cancellation update failed';
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'order_id', p_order_id,
        'status', 'cancelled',
        'filled_amount', v_order.filled_amount,
        'remaining_amount', v_order.amount - v_order.filled_amount
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_stop_limit_order(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_cond public.conditional_orders%ROWTYPE;
  v_parent public.orders%ROWTYPE;
  v_child public.orders%ROWTYPE;
  v_res public.order_reservations%ROWTYPE;
  v_cancel_result jsonb;
  v_final_status text;
  v_rows integer;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;

  SELECT * INTO v_cond
  FROM public.conditional_orders
  WHERE order_id=p_order_id AND user_id=v_uid AND order_kind='stop_limit'
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Stop-Limit order not found'; END IF;

  SELECT * INTO v_parent
  FROM public.orders
  WHERE id=p_order_id AND user_id=v_uid AND order_type='conditional'
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Parent order not found'; END IF;

  IF v_cond.status='pending' THEN
    SELECT * INTO v_res
    FROM public.order_reservations
    WHERE order_id=p_order_id AND user_id=v_uid
    FOR UPDATE;
    IF NOT FOUND OR v_res.status<>'reserved'
       OR v_res.consumed_amount<0 OR v_res.released_amount<0
       OR v_res.consumed_amount+v_res.released_amount>v_res.reserved_amount THEN
      RAISE EXCEPTION 'Valid active reservation not found';
    END IF;

    UPDATE public.order_reservations
    SET released_amount=reserved_amount-consumed_amount,
        status=CASE WHEN consumed_amount>=reserved_amount THEN 'consumed' ELSE 'released' END,
        updated_at=now()
    WHERE id=v_res.id AND status='reserved';
    GET DIAGNOSTICS v_rows=ROW_COUNT;
    IF v_rows<>1 THEN RAISE EXCEPTION 'Stop-Limit reservation release failed'; END IF;

    UPDATE public.orders
    SET status='cancelled',remaining_amount=amount-filled_amount
    WHERE id=p_order_id AND user_id=v_uid AND status='pending';
    GET DIAGNOSTICS v_rows=ROW_COUNT;
    IF v_rows<>1 THEN RAISE EXCEPTION 'Stop-Limit parent cancellation failed'; END IF;

    UPDATE public.conditional_orders
    SET status='cancelled',updated_at=now()
    WHERE id=v_cond.id AND status='pending';
    GET DIAGNOSTICS v_rows=ROW_COUNT;
    IF v_rows<>1 THEN RAISE EXCEPTION 'Stop-Limit cancellation state update failed'; END IF;

    RETURN jsonb_build_object('success',true,'status','cancelled','order_id',p_order_id,
      'released_amount',v_res.reserved_amount-v_res.consumed_amount);
  END IF;

  IF v_cond.status<>'triggered' OR v_cond.execution_order_id IS NULL THEN
    RAISE EXCEPTION 'Stop-Limit order is no longer cancellable';
  END IF;

  SELECT * INTO v_child
  FROM public.orders
  WHERE id=v_cond.execution_order_id AND user_id=v_uid AND order_type='limit'
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Triggered limit order not found'; END IF;

  IF v_child.status IN ('pending','partially_filled') THEN
    v_cancel_result:=public.cancel_limit_order(v_child.id);
    SELECT * INTO v_child FROM public.orders WHERE id=v_child.id AND user_id=v_uid;
  END IF;

  v_final_status := CASE
    WHEN v_child.status='filled' THEN 'filled'
    WHEN v_child.status='rejected' THEN 'rejected'
    ELSE 'cancelled'
  END;

  UPDATE public.orders
  SET status=v_final_status,
      filled_amount=v_child.filled_amount,
      remaining_amount=v_child.remaining_amount
  WHERE id=p_order_id AND user_id=v_uid AND status='triggered';
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 THEN RAISE EXCEPTION 'Stop-Limit parent state update failed'; END IF;

  UPDATE public.conditional_orders
  SET status=v_final_status,updated_at=now()
  WHERE id=v_cond.id AND status='triggered';
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 THEN RAISE EXCEPTION 'Stop-Limit state update failed'; END IF;

  RETURN jsonb_build_object('success',true,'status',v_final_status,
    'order_id',p_order_id,'execution_order_id',v_child.id,
    'filled_amount',v_child.filled_amount,'remaining_amount',v_child.remaining_amount);
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_admin_asset_refresh(p_coingecko_id text, p_admin_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_claimed boolean := false;
BEGIN
  IF p_admin_user_id IS NULL
     OR p_coingecko_id IS NULL
     OR pg_catalog.length(pg_catalog.btrim(p_coingecko_id)) NOT BETWEEN 1 AND 128 THEN
    RAISE EXCEPTION 'Invalid refresh request' USING errcode = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM private.admin_users a
    WHERE a.user_id = p_admin_user_id
      AND a.role = 'super_admin'
  ) THEN
    RAISE EXCEPTION 'Super administrator access required' USING errcode = '42501';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    742021,
    pg_catalog.hashtext(pg_catalog.btrim(p_coingecko_id))
  );

  INSERT INTO private.admin_asset_refresh_limits(
    coingecko_id, last_requested_at, requested_by
  )
  VALUES (pg_catalog.btrim(p_coingecko_id), pg_catalog.now(), p_admin_user_id)
  ON CONFLICT (coingecko_id) DO UPDATE
    SET last_requested_at = EXCLUDED.last_requested_at,
        requested_by = EXCLUDED.requested_by
    WHERE private.admin_asset_refresh_limits.last_requested_at
          <= pg_catalog.now() - interval '30 seconds'
  RETURNING true INTO v_claimed;

  IF NOT COALESCE(v_claimed, false) THEN
    RAISE EXCEPTION 'This asset was refreshed recently; wait 30 seconds'
      USING errcode = '55000';
  END IF;

  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.deactivate_my_account()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_cancelled integer:=0;
  v_released integer:=0;
  v_cond_cancelled integer:=0;
  v_cond_released integer:=0;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;

  UPDATE public.profiles
  SET is_active=false,deactivated_at=pg_catalog.now()
  WHERE id=v_uid AND is_active IS TRUE;

  IF NOT FOUND THEN
    IF EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=v_uid AND p.is_active IS FALSE) THEN
      RETURN jsonb_build_object('success',true,'status','inactive',
        'cancelled_orders',0,'released_reservations',0);
    END IF;
    RAISE EXCEPTION 'Account profile not found';
  END IF;

  UPDATE public.order_reservations r
  SET released_amount=r.reserved_amount-r.consumed_amount,
      status=CASE WHEN r.consumed_amount>=r.reserved_amount THEN 'consumed' ELSE 'released' END,
      updated_at=pg_catalog.now()
  FROM public.orders o
  WHERE r.order_id=o.id AND r.user_id=v_uid AND o.user_id=v_uid
    AND o.order_type='limit' AND o.status IN ('pending','partially_filled')
    AND r.status='reserved' AND r.consumed_amount>=0 AND r.consumed_amount<=r.reserved_amount;
  GET DIAGNOSTICS v_released=ROW_COUNT;

  UPDATE public.orders SET status='cancelled',remaining_amount=amount-filled_amount
  WHERE user_id=v_uid AND order_type='limit' AND status IN ('pending','partially_filled');
  GET DIAGNOSTICS v_cancelled=ROW_COUNT;

  UPDATE public.order_reservations r
  SET released_amount=r.reserved_amount-r.consumed_amount,
      status=CASE WHEN r.consumed_amount>=r.reserved_amount THEN 'consumed' ELSE 'released' END,
      updated_at=pg_catalog.now()
  FROM public.orders o JOIN public.conditional_orders c ON c.order_id=o.id
  WHERE r.order_id=o.id AND r.user_id=v_uid AND o.user_id=v_uid
    AND o.order_type='conditional' AND o.status='pending' AND c.status='pending'
    AND r.status='reserved' AND r.consumed_amount>=0
    AND r.consumed_amount<=r.reserved_amount;
  GET DIAGNOSTICS v_cond_released=ROW_COUNT;

  UPDATE public.orders SET status='cancelled',remaining_amount=amount-filled_amount
  WHERE user_id=v_uid AND order_type='conditional' AND status='pending';
  GET DIAGNOSTICS v_cond_cancelled=ROW_COUNT;

  -- The child Limit orders above have already been cancelled and released.
  -- Mirror their final state into triggered Stop-Limit parent records.
  UPDATE public.orders parent
  SET status=CASE child.status WHEN 'filled' THEN 'filled'
                               WHEN 'rejected' THEN 'rejected'
                               ELSE 'cancelled' END,
      filled_amount=child.filled_amount,
      remaining_amount=child.remaining_amount
  FROM public.conditional_orders c
  JOIN public.orders child ON child.id=c.execution_order_id AND child.user_id=c.user_id
  WHERE parent.id=c.order_id AND parent.user_id=c.user_id
    AND c.user_id=v_uid AND c.order_kind='stop_limit'
    AND c.status='triggered' AND parent.status='triggered';

  UPDATE public.conditional_orders
  SET status=CASE
    WHEN EXISTS (
      SELECT 1 FROM public.orders child
      WHERE child.id=conditional_orders.execution_order_id
        AND child.status='filled'
    ) THEN 'filled'
    WHEN EXISTS (
      SELECT 1 FROM public.orders child
      WHERE child.id=conditional_orders.execution_order_id
        AND child.status='rejected'
    ) THEN 'rejected'
    ELSE 'cancelled'
  END,
  updated_at=pg_catalog.now()
  WHERE user_id=v_uid AND order_kind='stop_limit' AND status='triggered';

  UPDATE public.conditional_orders
  SET status='cancelled',updated_at=pg_catalog.now()
  WHERE user_id=v_uid AND status='pending';

  RETURN jsonb_build_object('success',true,'status','inactive',
    'cancelled_orders',v_cancelled+v_cond_cancelled,
    'released_reservations',v_released+v_cond_released);
END;
$function$

CREATE OR REPLACE FUNCTION public.execute_demo_trade(p_symbol text, p_side text, p_amount numeric, p_price numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_uid uuid;
    v_symbol text;
    v_base text;
    v_side text;
    v_price numeric;
    v_balance numeric;
    v_asset_balance numeric;
    v_reserved numeric := 0;
    v_available numeric := 0;
    v_gross numeric;
    v_total numeric;
    v_fee numeric;
    v_fee_rate numeric;
    v_order_id uuid;
BEGIN
    v_uid := auth.uid();

    IF v_uid IS NULL THEN
        RAISE EXCEPTION 'Authentication required';
    END IF;

    IF NOT public.current_account_is_active() THEN
        RAISE EXCEPTION 'Account is inactive';
    END IF;

    v_symbol := upper(trim(p_symbol));
    v_side := lower(trim(p_side));

    IF v_symbol IS NULL
       OR v_symbol !~ '^[A-Z0-9]{2,15}USDT$' THEN
        RAISE EXCEPTION 'Unsupported trading pair';
    END IF;

    v_base := left(v_symbol, length(v_symbol) - 4);

    IF v_side IS NULL OR v_side NOT IN ('buy', 'sell')
       OR v_base = 'USDT' THEN
        RAISE EXCEPTION 'Invalid trade parameters';
    END IF;

    IF p_amount IS NULL OR p_amount <= 0 OR p_amount > 1000000 THEN
        RAISE EXCEPTION 'Invalid amount';
    END IF;

    PERFORM 1
    FROM public.demo_trading_pairs AS dp
    WHERE dp.pair_symbol = v_symbol
      AND dp.quote_asset = 'USDT'
      AND dp.is_enabled IS TRUE
    FOR SHARE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Trading pair is not enabled';
    END IF;

    SELECT mp.price
    INTO v_price
    FROM public.market_prices AS mp
    WHERE mp.symbol = v_symbol
      AND mp.updated_at >= now() - interval '1 minute'
    FOR SHARE;

    IF NOT FOUND OR v_price IS NULL OR v_price <= 0 THEN
        RAISE EXCEPTION 'Market price unavailable or outdated';
    END IF;

    v_fee_rate := public.get_demo_trading_fee_rate('USDT', 'taker');
    v_gross := round(p_amount * v_price, 8);
    v_fee := round(v_gross * v_fee_rate, 8);

    INSERT INTO public.wallets (user_id)
    VALUES (v_uid)
    ON CONFLICT (user_id) DO NOTHING;

    SELECT balance_usdt
    INTO v_balance
    FROM public.wallets
    WHERE user_id = v_uid
    FOR UPDATE;

    IF v_balance IS NULL THEN
        v_balance := 0;
    END IF;

    IF v_side = 'buy' THEN
        SELECT COALESCE(
            SUM(r.reserved_amount - r.released_amount - r.consumed_amount),
            0
        )
        INTO v_reserved
        FROM public.order_reservations AS r
        WHERE r.user_id = v_uid
          AND r.asset = 'USDT'
          AND r.status = 'reserved';

        v_available := v_balance - v_reserved;
        v_total := v_gross + v_fee;

        IF v_available < v_total THEN
            RAISE EXCEPTION 'Insufficient available USDT balance';
        END IF;

        UPDATE public.wallets
        SET balance_usdt = balance_usdt - v_total
        WHERE user_id = v_uid;

        INSERT INTO public.asset_balances (
            user_id, asset, balance, updated_at
        )
        VALUES (v_uid, v_base, p_amount, now())
        ON CONFLICT (user_id, asset)
        DO UPDATE SET
            balance = public.asset_balances.balance + EXCLUDED.balance,
            updated_at = now();
    ELSE
        INSERT INTO public.asset_balances (user_id, asset, balance)
        VALUES (v_uid, v_base, 0)
        ON CONFLICT (user_id, asset) DO NOTHING;

        SELECT balance
        INTO v_asset_balance
        FROM public.asset_balances
        WHERE user_id = v_uid
          AND asset = v_base
        FOR UPDATE;

        SELECT COALESCE(
            SUM(r.reserved_amount - r.released_amount - r.consumed_amount),
            0
        )
        INTO v_reserved
        FROM public.order_reservations AS r
        WHERE r.user_id = v_uid
          AND r.asset = v_base
          AND r.status = 'reserved';

        v_available := COALESCE(v_asset_balance, 0) - v_reserved;

        IF v_available < p_amount THEN
            RAISE EXCEPTION 'Insufficient available asset balance';
        END IF;

        v_total := v_gross - v_fee;

        UPDATE public.asset_balances
        SET balance = balance - p_amount,
            updated_at = now()
        WHERE user_id = v_uid
          AND asset = v_base;

        UPDATE public.wallets
        SET balance_usdt = balance_usdt + v_total
        WHERE user_id = v_uid;
    END IF;

    INSERT INTO public.orders (
        user_id, symbol, side, order_type, amount, price, status,
        filled_amount, remaining_amount
    )
    VALUES (
        v_uid, v_symbol, v_side, 'market', p_amount, v_price, 'filled',
        p_amount, 0
    )
    RETURNING id INTO v_order_id;

    INSERT INTO public.trades (
        order_id, user_id, symbol, side, amount, price
    )
    VALUES (
        v_order_id, v_uid, v_symbol, v_side, p_amount, v_price
    );

    INSERT INTO public.transactions (
        user_id, currency, amount, transaction_type, description
    )
    VALUES (
        v_uid, 'USDT', v_total, v_side,
        'DigiArz demo trade: ' || v_symbol
    );

    RETURN jsonb_build_object(
        'success', true,
        'order_id', v_order_id,
        'symbol', v_symbol,
        'side', v_side,
        'amount', p_amount,
        'price', v_price,
        'fee', v_fee,
        'total', v_total,
        'currency', 'USDT'
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_demo_trading_fee_rate(p_quote_asset text, p_liquidity_type text)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_rate numeric;
BEGIN
    IF p_liquidity_type NOT IN ('maker', 'taker') THEN
        RAISE EXCEPTION 'Invalid liquidity type';
    END IF;

    SELECT CASE WHEN p_liquidity_type = 'maker'
                THEN f.maker_fee_rate ELSE f.taker_fee_rate END
      INTO v_rate
      FROM public.demo_trading_fees AS f
     WHERE f.quote_asset = upper(btrim(p_quote_asset))
       AND f.is_enabled IS TRUE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Trading fee is not configured for quote asset %', p_quote_asset;
    END IF;

    RETURN v_rate;
END;
$function$

CREATE OR REPLACE FUNCTION public.place_conditional_exit_order(p_symbol text, p_order_kind text, p_amount numeric, p_trigger_price numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_symbol text := upper(btrim(p_symbol));
  v_kind text := lower(btrim(p_order_kind));
  v_base text;
  v_wallet numeric;
  v_balance numeric;
  v_reserved numeric := 0;
  v_order_id uuid;
  v_conditional_id uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF NOT public.current_account_is_active() THEN RAISE EXCEPTION 'Account is inactive'; END IF;
  IF v_symbol IS NULL OR v_symbol !~ '^[A-Z0-9]{2,15}USDT$' THEN
    RAISE EXCEPTION 'Invalid trading symbol';
  END IF;
  IF v_kind NOT IN ('take_profit','stop_loss') THEN RAISE EXCEPTION 'Invalid conditional order kind'; END IF;
  IF p_amount IS NULL OR p_amount <= 0 OR p_amount > 1000000 THEN
    RAISE EXCEPTION 'Invalid order amount';
  END IF;
  IF p_trigger_price IS NULL OR p_trigger_price <= 0 THEN
    RAISE EXCEPTION 'Invalid trigger price';
  END IF;
  v_base := left(v_symbol,length(v_symbol)-4);
  IF v_base IS NULL OR v_base='' OR v_base='USDT' THEN RAISE EXCEPTION 'Invalid base asset'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.demo_trading_pairs p
    WHERE p.pair_symbol=v_symbol AND p.quote_asset='USDT' AND p.is_enabled IS TRUE
  ) THEN RAISE EXCEPTION 'Trading pair is not enabled'; END IF;

  SELECT w.balance_usdt INTO v_wallet
  FROM public.wallets w WHERE w.user_id=v_uid FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'User wallet not found'; END IF;

  SELECT ab.balance INTO v_balance
  FROM public.asset_balances ab
  WHERE ab.user_id=v_uid AND ab.asset=v_base FOR UPDATE;
  IF NOT FOUND THEN v_balance:=0; END IF;

  SELECT COALESCE(sum(greatest(r.reserved_amount-r.consumed_amount-r.released_amount,0)),0)
  INTO v_reserved
  FROM public.order_reservations r
  WHERE r.user_id=v_uid AND r.asset=v_base AND r.status='reserved';

  IF v_balance-v_reserved < p_amount THEN
    RAISE EXCEPTION 'Insufficient available asset balance';
  END IF;

  INSERT INTO public.orders(
    user_id,symbol,side,order_type,amount,price,status,filled_amount,remaining_amount
  ) VALUES(v_uid,v_symbol,'sell','conditional',p_amount,p_trigger_price,'pending',0,p_amount)
  RETURNING id INTO v_order_id;

  INSERT INTO public.order_reservations(
    order_id,user_id,asset,reserved_amount,released_amount,consumed_amount,status
  ) VALUES(v_order_id,v_uid,v_base,p_amount,0,0,'reserved');

  INSERT INTO public.conditional_orders(
    order_id,user_id,symbol,side,order_kind,trigger_price,amount
  ) VALUES(v_order_id,v_uid,v_symbol,'sell',v_kind,p_trigger_price,p_amount)
  RETURNING id INTO v_conditional_id;

  RETURN jsonb_build_object(
    'success',true,'conditional_order_id',v_conditional_id,'order_id',v_order_id,
    'symbol',v_symbol,'side','sell','order_kind',v_kind,'trigger_price',p_trigger_price,
    'amount',p_amount,'reserved_asset',v_base,'reserved_amount',p_amount,'status','pending'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.place_limit_order(p_symbol text, p_side text, p_amount numeric, p_limit_price numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_uid uuid;
    v_symbol text;
    v_side text;
    v_base_asset text;
    v_asset text;
    v_wallet_balance numeric := 0;
    v_asset_balance numeric := 0;
    v_reserved_balance numeric := 0;
    v_required_amount numeric := 0;
    v_order_id uuid;
    v_fee_rate numeric;
BEGIN
    v_uid := auth.uid();

    IF v_uid IS NULL THEN
        RAISE EXCEPTION 'Authentication required';
    END IF;

    IF NOT public.current_account_is_active() THEN
        RAISE EXCEPTION 'Account is inactive';
    END IF;

    v_symbol := upper(btrim(p_symbol));
    v_side := lower(btrim(p_side));

    IF v_symbol IS NULL
       OR v_symbol !~ '^[A-Z0-9]{2,15}USDT$' THEN
        RAISE EXCEPTION 'Invalid trading symbol';
    END IF;

    IF v_side IS NULL OR v_side NOT IN ('buy', 'sell') THEN
        RAISE EXCEPTION 'Order side must be buy or sell';
    END IF;

    IF p_amount IS NULL OR p_amount <= 0 OR p_amount > 1000000 THEN
        RAISE EXCEPTION 'Invalid order amount';
    END IF;

    IF p_limit_price IS NULL OR p_limit_price <= 0 THEN
        RAISE EXCEPTION 'Invalid limit price';
    END IF;

    v_base_asset := left(v_symbol, length(v_symbol) - 4);

    IF v_base_asset = '' OR v_base_asset = 'USDT' THEN
        RAISE EXCEPTION 'Invalid base asset';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.demo_trading_pairs AS p
        WHERE p.pair_symbol = v_symbol
          AND p.quote_asset = 'USDT'
          AND p.is_enabled IS TRUE
    ) THEN
        RAISE EXCEPTION 'Trading pair is not enabled';
    END IF;

    SELECT w.balance_usdt
    INTO v_wallet_balance
    FROM public.wallets AS w
    WHERE w.user_id = v_uid
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'User wallet not found';
    END IF;

    v_fee_rate := public.get_demo_trading_fee_rate('USDT', 'maker');
    IF v_side = 'buy' THEN
        v_asset := 'USDT';
        v_required_amount := p_amount * p_limit_price * (1 + v_fee_rate);

        SELECT COALESCE(
            SUM(GREATEST(
                r.reserved_amount - r.consumed_amount - r.released_amount,
                0
            )),
            0
        )
        INTO v_reserved_balance
        FROM public.order_reservations AS r
        WHERE r.user_id = v_uid
          AND r.asset = v_asset
          AND r.status = 'reserved';

        IF v_wallet_balance - v_reserved_balance < v_required_amount THEN
            RAISE EXCEPTION 'Insufficient available USDT balance';
        END IF;
    ELSE
        v_asset := v_base_asset;

        SELECT COALESCE(ab.balance, 0)
        INTO v_asset_balance
        FROM public.asset_balances AS ab
        WHERE ab.user_id = v_uid
          AND ab.asset = v_asset
        FOR UPDATE;

        IF NOT FOUND THEN
            v_asset_balance := 0;
        END IF;

        SELECT COALESCE(
            SUM(GREATEST(
                r.reserved_amount - r.consumed_amount - r.released_amount,
                0
            )),
            0
        )
        INTO v_reserved_balance
        FROM public.order_reservations AS r
        WHERE r.user_id = v_uid
          AND r.asset = v_asset
          AND r.status = 'reserved';

        IF v_asset_balance - v_reserved_balance < p_amount THEN
            RAISE EXCEPTION 'Insufficient available asset balance';
        END IF;

        v_required_amount := p_amount;
    END IF;

    INSERT INTO public.orders (
        user_id, symbol, side, order_type, amount, price, status,
        filled_amount, remaining_amount
    )
    VALUES (
        v_uid, v_symbol, v_side, 'limit', p_amount, p_limit_price,
        'pending', 0, p_amount
    )
    RETURNING id INTO v_order_id;

    INSERT INTO public.order_reservations (
        order_id, user_id, asset, reserved_amount,
        released_amount, consumed_amount, status
    )
    VALUES (
        v_order_id, v_uid, v_asset, v_required_amount,
        0, 0, 'reserved'
    );

    RETURN jsonb_build_object(
        'success', true,
        'message', 'Limit order placed successfully',
        'order_id', v_order_id,
        'symbol', v_symbol,
        'side', v_side,
        'order_type', 'limit',
        'amount', p_amount,
        'limit_price', p_limit_price,
        'reserved_asset', v_asset,
        'reserved_amount', v_required_amount,
        'fee_rate', v_fee_rate,
        'status', 'pending'
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.place_stop_limit_order(p_symbol text, p_side text, p_amount numeric, p_stop_price numeric, p_limit_price numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_symbol text := upper(btrim(p_symbol));
  v_side text := lower(btrim(p_side));
  v_base text;
  v_wallet numeric := 0;
  v_asset_balance numeric := 0;
  v_reserved numeric := 0;
  v_required numeric := 0;
  v_fee_rate numeric := 0;
  v_reserve_asset text;
  v_order_id uuid;
  v_conditional_id uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF NOT public.current_account_is_active() THEN RAISE EXCEPTION 'Account is inactive'; END IF;
  IF v_symbol IS NULL OR v_symbol !~ '^[A-Z0-9]{2,15}USDT$' THEN
    RAISE EXCEPTION 'Invalid trading symbol';
  END IF;
  IF v_side IS NULL OR v_side NOT IN ('buy','sell') THEN
    RAISE EXCEPTION 'Order side must be buy or sell';
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 OR p_amount > 1000000 THEN
    RAISE EXCEPTION 'Invalid order amount';
  END IF;
  IF p_stop_price IS NULL OR p_stop_price <= 0
     OR p_limit_price IS NULL OR p_limit_price <= 0 THEN
    RAISE EXCEPTION 'Stop and limit prices must be positive';
  END IF;
  IF (v_side='buy' AND p_limit_price < p_stop_price)
     OR (v_side='sell' AND p_limit_price > p_stop_price) THEN
    RAISE EXCEPTION 'Invalid stop-limit price relationship';
  END IF;

  v_base := left(v_symbol,length(v_symbol)-4);
  IF v_base IS NULL OR v_base='' OR v_base='USDT' THEN
    RAISE EXCEPTION 'Invalid base asset';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.demo_trading_pairs p
    WHERE p.pair_symbol=v_symbol AND p.quote_asset='USDT' AND p.is_enabled IS TRUE
  ) THEN RAISE EXCEPTION 'Trading pair is not enabled'; END IF;

  -- Match the wallet-first lock order used by the existing trading RPCs.
  SELECT w.balance_usdt INTO v_wallet
  FROM public.wallets w WHERE w.user_id=v_uid FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'User wallet not found'; END IF;

  v_fee_rate := public.get_demo_trading_fee_rate('USDT','maker');
  IF v_side='buy' THEN
    v_reserve_asset := 'USDT';
    v_required := p_amount*p_limit_price*(1+v_fee_rate);
    SELECT COALESCE(sum(greatest(r.reserved_amount-r.consumed_amount-r.released_amount,0)),0)
      INTO v_reserved
    FROM public.order_reservations r
    WHERE r.user_id=v_uid AND r.asset='USDT' AND r.status='reserved';
    IF v_wallet-v_reserved < v_required THEN
      RAISE EXCEPTION 'Insufficient available USDT balance';
    END IF;
  ELSE
    v_reserve_asset := v_base;
    SELECT COALESCE(ab.balance,0) INTO v_asset_balance
    FROM public.asset_balances ab
    WHERE ab.user_id=v_uid AND ab.asset=v_base FOR UPDATE;
    IF NOT FOUND THEN v_asset_balance:=0; END IF;
    SELECT COALESCE(sum(greatest(r.reserved_amount-r.consumed_amount-r.released_amount,0)),0)
      INTO v_reserved
    FROM public.order_reservations r
    WHERE r.user_id=v_uid AND r.asset=v_base AND r.status='reserved';
    v_required := p_amount;
    IF v_asset_balance-v_reserved < v_required THEN
      RAISE EXCEPTION 'Insufficient available asset balance';
    END IF;
  END IF;

  INSERT INTO public.orders(
    user_id,symbol,side,order_type,amount,price,status,filled_amount,remaining_amount
  ) VALUES(v_uid,v_symbol,v_side,'conditional',p_amount,p_limit_price,'pending',0,p_amount)
  RETURNING id INTO v_order_id;

  INSERT INTO public.order_reservations(
    order_id,user_id,asset,reserved_amount,released_amount,consumed_amount,status
  ) VALUES(v_order_id,v_uid,v_reserve_asset,v_required,0,0,'reserved');

  INSERT INTO public.conditional_orders(
    order_id,user_id,symbol,side,order_kind,trigger_price,limit_price,amount
  ) VALUES(v_order_id,v_uid,v_symbol,v_side,'stop_limit',p_stop_price,p_limit_price,p_amount)
  RETURNING id INTO v_conditional_id;

  RETURN jsonb_build_object(
    'success',true,'conditional_order_id',v_conditional_id,'order_id',v_order_id,
    'symbol',v_symbol,'side',v_side,'order_kind','stop_limit',
    'stop_price',p_stop_price,'limit_price',p_limit_price,'amount',p_amount,
    'reserved_asset',v_reserve_asset,'reserved_amount',v_required,'status','pending'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.process_conditional_orders()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_cond record;
  v_res public.order_reservations%ROWTYPE;
  v_market_price numeric;
  v_result jsonb;
  v_execution_order_id uuid;
  v_processed integer:=0;
  v_triggered integer:=0;
  v_rejected integer:=0;
  v_skipped integer:=0;
  v_rows integer;
BEGIN
  IF NOT pg_catalog.pg_try_advisory_xact_lock(739201127) THEN
    RETURN jsonb_build_object('success',true,'message','Another conditional cycle is running','processed',0);
  END IF;

  FOR v_cond IN
    SELECT c.id,c.order_id,c.user_id,c.symbol,c.order_kind,c.trigger_price,c.amount,
           o.filled_amount,o.remaining_amount
    FROM public.conditional_orders c
    JOIN public.orders o ON o.id=c.order_id AND o.user_id=c.user_id
    JOIN public.profiles p ON p.id=c.user_id AND p.is_active IS TRUE
    WHERE c.status='pending' AND o.status='pending' AND o.order_type='conditional'
    ORDER BY c.created_at
    FOR UPDATE OF c,o SKIP LOCKED
  LOOP
    IF v_cond.symbol IS NULL OR v_cond.symbol !~ '^[A-Z0-9]{2,15}USDT$'
       OR v_cond.amount IS NULL OR v_cond.amount<=0
       OR v_cond.trigger_price IS NULL OR v_cond.trigger_price<=0 THEN
      v_skipped:=v_skipped+1; CONTINUE;
    END IF;

    SELECT mp.price INTO v_market_price
    FROM public.market_prices mp
    WHERE mp.symbol=v_cond.symbol
      AND mp.updated_at>=now()-interval '1 minute'
    FOR SHARE;
    IF NOT FOUND OR v_market_price IS NULL OR v_market_price<=0 THEN
      v_skipped:=v_skipped+1; CONTINUE;
    END IF;

    IF (v_cond.order_kind='take_profit' AND v_market_price<v_cond.trigger_price)
       OR (v_cond.order_kind='stop_loss' AND v_market_price>v_cond.trigger_price) THEN
      v_skipped:=v_skipped+1; CONTINUE;
    END IF;

    SELECT * INTO v_res
    FROM public.order_reservations r
    WHERE r.order_id=v_cond.order_id AND r.user_id=v_cond.user_id
    FOR UPDATE;
    IF NOT FOUND OR v_res.status<>'reserved'
       OR v_res.asset<>left(v_cond.symbol,length(v_cond.symbol)-4)
       OR v_res.reserved_amount<v_cond.amount
       OR v_res.consumed_amount<0
       OR v_res.consumed_amount+v_res.released_amount>v_res.reserved_amount THEN
      UPDATE public.conditional_orders
      SET attempt_count=attempt_count+1,last_error='Reservation validation failed',updated_at=now()
      WHERE id=v_cond.id;
      v_skipped:=v_skipped+1; CONTINUE;
    END IF;

    BEGIN
      -- Release this order's own reservation inside the same transaction before
      -- calling the market engine; if execution fails, this subtransaction rolls back.
      UPDATE public.order_reservations
      SET released_amount=reserved_amount-consumed_amount,
          status='released',updated_at=now()
      WHERE id=v_res.id AND status='reserved';

      PERFORM pg_catalog.set_config('request.jwt.claim.sub',v_cond.user_id::text,true);
      PERFORM pg_catalog.set_config('request.jwt.claims',
        pg_catalog.jsonb_build_object('sub',v_cond.user_id::text,'role','authenticated')::text,true);

      v_result:=public.execute_demo_trade(v_cond.symbol,'sell',v_cond.amount,v_market_price);
      IF COALESCE((v_result->>'success')::boolean,false) IS NOT TRUE THEN
        RAISE EXCEPTION 'Market engine did not confirm conditional execution';
      END IF;
      v_execution_order_id:=(v_result->>'order_id')::uuid;

      UPDATE public.order_reservations
      SET consumed_amount=reserved_amount,released_amount=0,status='consumed',updated_at=now()
      WHERE id=v_res.id AND status='released'
        AND consumed_amount=0 AND released_amount=reserved_amount;
      GET DIAGNOSTICS v_rows=ROW_COUNT;
      IF v_rows<>1 THEN RAISE EXCEPTION 'Conditional reservation consumption update failed'; END IF;

      UPDATE public.orders
      SET status='filled',filled_amount=amount,remaining_amount=0
      WHERE id=v_cond.order_id AND user_id=v_cond.user_id AND status='pending';
      GET DIAGNOSTICS v_rows=ROW_COUNT;
      IF v_rows<>1 THEN RAISE EXCEPTION 'Conditional parent order update failed'; END IF;

      UPDATE public.conditional_orders
      SET status='filled',execution_order_id=v_execution_order_id,
          executed_price=(v_result->>'price')::numeric,
          triggered_at=now(),executed_at=now(),last_error=NULL,updated_at=now()
      WHERE id=v_cond.id AND status='pending';
      GET DIAGNOSTICS v_rows=ROW_COUNT;
      IF v_rows<>1 THEN RAISE EXCEPTION 'Conditional order completion update failed'; END IF;

      PERFORM pg_catalog.set_config('request.jwt.claim.sub','',true);
      PERFORM pg_catalog.set_config('request.jwt.claims','',true);
      v_processed:=v_processed+1;
      v_triggered:=v_triggered+1;
    EXCEPTION WHEN OTHERS THEN
      PERFORM pg_catalog.set_config('request.jwt.claim.sub','',true);
      PERFORM pg_catalog.set_config('request.jwt.claims','',true);
      -- The failed execution block rolled back the reservation release.
      UPDATE public.conditional_orders
      SET attempt_count=attempt_count+1,last_error=left(SQLERRM,500),updated_at=now()
      WHERE id=v_cond.id;
      SELECT * INTO v_res FROM public.order_reservations WHERE order_id=v_cond.order_id AND user_id=v_cond.user_id FOR UPDATE;
      IF FOUND AND (SELECT attempt_count FROM public.conditional_orders WHERE id=v_cond.id)>=10
         AND v_res.status='reserved'
         AND v_res.consumed_amount>=0
         AND v_res.consumed_amount+v_res.released_amount<=v_res.reserved_amount THEN
        UPDATE public.order_reservations
        SET released_amount=reserved_amount-consumed_amount,status='released',updated_at=now()
        WHERE id=v_res.id;
        UPDATE public.orders SET status='rejected',remaining_amount=amount-filled_amount
        WHERE id=v_cond.order_id AND user_id=v_cond.user_id AND status='pending';
        UPDATE public.conditional_orders
        SET status='rejected',updated_at=now()
        WHERE id=v_cond.id AND status='pending';
        v_rejected:=v_rejected+1;
      ELSE
        v_skipped:=v_skipped+1;
      END IF;
    END;
  END LOOP;

  RETURN jsonb_build_object('success',true,'processed',v_processed,
    'triggered',v_triggered,'rejected',v_rejected,'skipped',v_skipped);
END;
$function$

CREATE OR REPLACE FUNCTION public.process_limit_orders()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_order RECORD;
    v_reservation RECORD;
    v_market_price numeric;
    v_qty numeric;
    v_gross numeric;
    v_fee numeric;
    v_fee_rate numeric;
    v_total numeric;
    v_net numeric;
    v_remaining numeric;
    v_new_filled numeric;
    v_new_remaining numeric;
    v_consumed numeric;
    v_released numeric;
    v_target_remaining_reserve numeric;
    v_base_asset text;
    v_processed integer := 0;
    v_partial integer := 0;
    v_completed integer := 0;
    v_skipped integer := 0;
    v_rows integer;
BEGIN
    IF NOT pg_catalog.pg_try_advisory_xact_lock(739201126) THEN
        RETURN jsonb_build_object(
            'success', true,
            'message', 'Another execution cycle is running',
            'processed', 0
        );
    END IF;

    FOR v_order IN
        SELECT
            o.id,
            o.user_id,
            o.symbol,
            o.side,
            o.amount,
            o.price,
            o.filled_amount,
            o.remaining_amount
        FROM public.orders AS o
        WHERE o.order_type = 'limit'
          AND o.status IN ('pending', 'partially_filled')
          AND o.remaining_amount > 0
          AND EXISTS (SELECT 1 FROM public.profiles AS p WHERE p.id = o.user_id AND p.is_active IS TRUE)
        ORDER BY o.created_at ASC
        FOR UPDATE SKIP LOCKED
    LOOP
        IF v_order.symbol IS NULL
           OR v_order.symbol !~ '^[A-Z0-9]{2,15}USDT$'
           OR v_order.side IS NULL
           OR v_order.side NOT IN ('buy', 'sell')
           OR v_order.amount IS NULL
           OR v_order.amount <= 0
           OR v_order.price IS NULL
           OR v_order.price <= 0
           OR v_order.remaining_amount IS NULL
           OR v_order.remaining_amount <= 0 THEN
            v_skipped := v_skipped + 1;
            CONTINUE;
        END IF;

        v_base_asset := left(v_order.symbol, length(v_order.symbol) - 4);

        IF v_base_asset = '' OR v_base_asset = 'USDT' THEN
            v_skipped := v_skipped + 1;
            CONTINUE;
        END IF;

        IF NOT EXISTS (
            SELECT 1
            FROM public.demo_trading_pairs AS p
            WHERE p.pair_symbol = v_order.symbol
              AND p.quote_asset = 'USDT'
              AND p.is_enabled IS TRUE
        ) THEN
            v_skipped := v_skipped + 1;
            CONTINUE;
        END IF;

        SELECT mp.price
        INTO v_market_price
        FROM public.market_prices AS mp
        WHERE mp.symbol = v_order.symbol
          AND mp.updated_at >= now() - interval '1 minute';

        IF NOT FOUND OR v_market_price IS NULL OR v_market_price <= 0 THEN
            v_skipped := v_skipped + 1;
            CONTINUE;
        END IF;

        IF v_order.side = 'buy' AND v_market_price > v_order.price THEN
            v_skipped := v_skipped + 1;
            CONTINUE;
        END IF;

        IF v_order.side = 'sell' AND v_market_price < v_order.price THEN
            v_skipped := v_skipped + 1;
            CONTINUE;
        END IF;

        SELECT
            r.id,
            r.user_id,
            r.asset,
            r.reserved_amount,
            r.consumed_amount,
            r.released_amount,
            r.status
        INTO v_reservation
        FROM public.order_reservations AS r
        WHERE r.order_id = v_order.id
        FOR UPDATE;

        IF NOT FOUND
           OR v_reservation.user_id <> v_order.user_id
           OR v_reservation.status <> 'reserved'
           OR v_reservation.reserved_amount <= 0
           OR v_reservation.consumed_amount < 0
           OR v_reservation.released_amount < 0
           OR v_reservation.consumed_amount + v_reservation.released_amount
                > v_reservation.reserved_amount THEN
            v_skipped := v_skipped + 1;
            CONTINUE;
        END IF;

        -- Keep the same wallet-first lock order as trade placement.
        PERFORM 1
        FROM public.wallets AS w
        WHERE w.user_id = v_order.user_id
        FOR UPDATE;

        IF NOT FOUND THEN
            v_skipped := v_skipped + 1;
            CONTINUE;
        END IF;

        v_remaining := v_order.remaining_amount;
        v_qty := LEAST(v_remaining, v_order.amount * 0.25);

        IF v_qty <= 0 THEN
            v_skipped := v_skipped + 1;
            CONTINUE;
        END IF;

        v_gross := v_qty * v_market_price;
        v_fee_rate := public.get_demo_trading_fee_rate('USDT', 'maker');
        v_fee := v_gross * v_fee_rate;

        IF v_order.side = 'buy' THEN
            v_total := v_gross + v_fee;
            v_net := 0;

            IF v_reservation.asset <> 'USDT'
               OR v_reservation.consumed_amount
                  + v_reservation.released_amount + v_total
                  > v_reservation.reserved_amount THEN
                v_skipped := v_skipped + 1;
                CONTINUE;
            END IF;

            UPDATE public.wallets
            SET balance_usdt = balance_usdt - v_total
            WHERE user_id = v_order.user_id
              AND balance_usdt >= v_total;

            IF NOT FOUND THEN
                v_skipped := v_skipped + 1;
                CONTINUE;
            END IF;

            INSERT INTO public.asset_balances (
                user_id, asset, balance, updated_at
            )
            VALUES (
                v_order.user_id, v_base_asset, v_qty, now()
            )
            ON CONFLICT (user_id, asset)
            DO UPDATE SET
                balance = public.asset_balances.balance + EXCLUDED.balance,
                updated_at = now();
        ELSE
            v_total := 0;
            v_net := v_gross - v_fee;

            IF v_reservation.asset <> v_base_asset
               OR v_reservation.consumed_amount
                  + v_reservation.released_amount + v_qty
                  > v_reservation.reserved_amount THEN
                v_skipped := v_skipped + 1;
                CONTINUE;
            END IF;

            UPDATE public.asset_balances
            SET balance = balance - v_qty,
                updated_at = now()
            WHERE user_id = v_order.user_id
              AND asset = v_base_asset
              AND balance >= v_qty;

            IF NOT FOUND THEN
                v_skipped := v_skipped + 1;
                CONTINUE;
            END IF;

            UPDATE public.wallets
            SET balance_usdt = balance_usdt + v_net
            WHERE user_id = v_order.user_id;

            IF NOT FOUND THEN
                RAISE EXCEPTION 'Wallet not found for order %', v_order.id;
            END IF;
        END IF;

        v_new_filled := v_order.filled_amount + v_qty;
        v_new_remaining := GREATEST(v_order.amount - v_new_filled, 0);

        UPDATE public.orders
        SET filled_amount = v_new_filled,
            remaining_amount = v_new_remaining,
            status = CASE
                WHEN v_new_remaining <= 0 THEN 'filled'
                ELSE 'partially_filled'
            END
        WHERE id = v_order.id
          AND user_id = v_order.user_id;

        GET DIAGNOSTICS v_rows = ROW_COUNT;

        IF v_rows <> 1 THEN
            RAISE EXCEPTION 'Order update failed for order %', v_order.id;
        END IF;

        IF v_order.side = 'buy' THEN
            v_consumed := v_reservation.consumed_amount + v_total;
            v_target_remaining_reserve :=
                v_new_remaining * v_order.price * (1 + v_fee_rate);
        ELSE
            v_consumed := v_reservation.consumed_amount + v_qty;
            v_target_remaining_reserve := v_new_remaining;
        END IF;

        v_released := GREATEST(
            v_reservation.released_amount,
            v_reservation.reserved_amount
                - v_consumed
                - v_target_remaining_reserve
        );

        v_released := LEAST(
            v_released,
            v_reservation.reserved_amount - v_consumed
        );

        UPDATE public.order_reservations
        SET consumed_amount = v_consumed,
            released_amount = v_released,
            status = CASE
                WHEN v_new_remaining <= 0 THEN
                    CASE WHEN v_released > 0 THEN 'released'
                         ELSE 'consumed' END
                ELSE 'reserved'
            END,
            updated_at = now()
        WHERE id = v_reservation.id
          AND order_id = v_order.id
          AND user_id = v_order.user_id
          AND status = 'reserved';

        GET DIAGNOSTICS v_rows = ROW_COUNT;

        IF v_rows <> 1 THEN
            RAISE EXCEPTION 'Reservation update failed for order %', v_order.id;
        END IF;

        INSERT INTO public.trades (
            order_id, user_id, symbol, side, amount, price
        )
        VALUES (
            v_order.id, v_order.user_id, v_order.symbol,
            v_order.side, v_qty, v_market_price
        );

        IF v_order.side = 'buy' THEN
            INSERT INTO public.transactions (
                user_id, currency, amount, transaction_type, description
            )
            VALUES (
                v_order.user_id, 'USDT', v_total,
                'limit_buy', 'Limit buy execution: ' || v_order.symbol
            );
        ELSE
            INSERT INTO public.transactions (
                user_id, currency, amount, transaction_type, description
            )
            VALUES (
                v_order.user_id, 'USDT', v_net,
                'limit_sell', 'Limit sell execution: ' || v_order.symbol
            );
        END IF;

        v_processed := v_processed + 1;

        IF v_new_remaining <= 0 THEN
            v_completed := v_completed + 1;
        ELSE
            v_partial := v_partial + 1;
        END IF;
    END LOOP;

    RETURN jsonb_build_object(
        'success', true,
        'processed', v_processed,
        'partially_filled', v_partial,
        'completed', v_completed,
        'skipped', v_skipped,
        'fee_rate', v_fee_rate
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.process_stop_limit_orders()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_cond record;
  v_res public.order_reservations%ROWTYPE;
  v_market_price numeric;
  v_result jsonb;
  v_child_id uuid;
  v_attempt integer;
  v_processed integer:=0;
  v_triggered integer:=0;
  v_synced integer:=0;
  v_rejected integer:=0;
  v_skipped integer:=0;
  v_rows integer;
BEGIN
  IF NOT pg_catalog.pg_try_advisory_xact_lock(739201128) THEN
    RETURN jsonb_build_object('success',true,'message','Another Stop-Limit cycle is running','processed',0);
  END IF;

  -- Keep the parent order in sync with its child Limit order after triggering.
  FOR v_cond IN
    SELECT c.id,c.order_id,c.user_id,c.execution_order_id,
           child.status AS child_status,child.filled_amount AS child_filled,
           child.remaining_amount AS child_remaining
    FROM public.conditional_orders c
    JOIN public.orders parent ON parent.id=c.order_id AND parent.user_id=c.user_id
    JOIN public.orders child ON child.id=c.execution_order_id AND child.user_id=c.user_id
    WHERE c.order_kind='stop_limit' AND c.status='triggered'
    ORDER BY c.updated_at
    FOR UPDATE OF c,parent SKIP LOCKED
  LOOP
    IF v_cond.child_status IN ('filled','cancelled','rejected') THEN
      UPDATE public.orders
      SET status=v_cond.child_status,
          filled_amount=v_cond.child_filled,
          remaining_amount=v_cond.child_remaining
      WHERE id=v_cond.order_id AND user_id=v_cond.user_id AND status='triggered';
      UPDATE public.conditional_orders
      SET status=v_cond.child_status,updated_at=now()
      WHERE id=v_cond.id AND status='triggered';
    ELSE
      UPDATE public.orders
      SET filled_amount=v_cond.child_filled,
          remaining_amount=v_cond.child_remaining
      WHERE id=v_cond.order_id AND user_id=v_cond.user_id AND status='triggered';
    END IF;
    v_synced:=v_synced+1;
  END LOOP;

  FOR v_cond IN
    SELECT c.id,c.order_id,c.user_id,c.symbol,c.side,c.trigger_price,c.limit_price,c.amount
    FROM public.conditional_orders c
    JOIN public.orders o ON o.id=c.order_id AND o.user_id=c.user_id
    JOIN public.profiles p ON p.id=c.user_id AND p.is_active IS TRUE
    WHERE c.order_kind='stop_limit' AND c.status='pending'
      AND o.status='pending' AND o.order_type='conditional'
    ORDER BY c.created_at
    FOR UPDATE OF c,o SKIP LOCKED
  LOOP
    IF v_cond.symbol IS NULL OR v_cond.symbol !~ '^[A-Z0-9]{2,15}USDT$'
       OR v_cond.side NOT IN ('buy','sell')
       OR v_cond.amount IS NULL OR v_cond.amount<=0
       OR v_cond.trigger_price IS NULL OR v_cond.trigger_price<=0
       OR v_cond.limit_price IS NULL OR v_cond.limit_price<=0
       OR (v_cond.side='buy' AND v_cond.limit_price<v_cond.trigger_price)
       OR (v_cond.side='sell' AND v_cond.limit_price>v_cond.trigger_price) THEN
      v_skipped:=v_skipped+1;
      CONTINUE;
    END IF;

    SELECT mp.price INTO v_market_price
    FROM public.market_prices mp
    WHERE mp.symbol=v_cond.symbol
      AND mp.updated_at>=now()-interval '1 minute'
    FOR SHARE;
    IF NOT FOUND OR v_market_price IS NULL OR v_market_price<=0 THEN
      v_skipped:=v_skipped+1;
      CONTINUE;
    END IF;

    IF (v_cond.side='buy' AND v_market_price<v_cond.trigger_price)
       OR (v_cond.side='sell' AND v_market_price>v_cond.trigger_price) THEN
      v_skipped:=v_skipped+1;
      CONTINUE;
    END IF;

    SELECT * INTO v_res
    FROM public.order_reservations r
    WHERE r.order_id=v_cond.order_id AND r.user_id=v_cond.user_id
    FOR UPDATE;
    IF NOT FOUND OR v_res.status<>'reserved'
       OR v_res.reserved_amount<=0 OR v_res.consumed_amount<0
       OR v_res.released_amount<0
       OR v_res.consumed_amount+v_res.released_amount>v_res.reserved_amount
       OR (v_cond.side='buy' AND v_res.asset<>'USDT')
       OR (v_cond.side='sell' AND v_res.asset<>left(v_cond.symbol,length(v_cond.symbol)-4)) THEN
      UPDATE public.conditional_orders
      SET attempt_count=attempt_count+1,
          last_error='Reservation validation failed; manual review required',
          updated_at=now()
      WHERE id=v_cond.id
      RETURNING attempt_count INTO v_attempt;

      IF v_attempt>=10 THEN
        -- Fail closed: stop retrying, but never release an invalid reservation.
        -- An operator must reconcile ownership and arithmetic before recovery.
        UPDATE public.orders
        SET status='rejected',remaining_amount=amount-filled_amount
        WHERE id=v_cond.order_id AND user_id=v_cond.user_id AND status='pending';

        UPDATE public.conditional_orders
        SET status='rejected',updated_at=now()
        WHERE id=v_cond.id AND status='pending';

        v_rejected:=v_rejected+1;
      ELSE
        v_skipped:=v_skipped+1;
      END IF;
      CONTINUE;
    END IF;

    BEGIN
      -- Release the trigger-stage reservation and create a fresh Limit reservation
      -- atomically. If placing the child order fails, the subtransaction restores it.
      UPDATE public.order_reservations
      SET released_amount=reserved_amount-consumed_amount,
          status='released',updated_at=now()
      WHERE id=v_res.id AND status='reserved';

      PERFORM pg_catalog.set_config('request.jwt.claim.sub',v_cond.user_id::text,true);
      PERFORM pg_catalog.set_config('request.jwt.claims',
        pg_catalog.jsonb_build_object('sub',v_cond.user_id::text,'role','authenticated')::text,true);

      v_result:=public.place_limit_order(v_cond.symbol,v_cond.side,v_cond.amount,v_cond.limit_price);
      IF COALESCE((v_result->>'success')::boolean,false) IS NOT TRUE THEN
        RAISE EXCEPTION 'Limit engine did not confirm Stop-Limit trigger';
      END IF;
      v_child_id:=(v_result->>'order_id')::uuid;
      IF v_child_id IS NULL THEN RAISE EXCEPTION 'Stop-Limit child order id missing'; END IF;

      UPDATE public.orders
      SET status='triggered',filled_amount=0,remaining_amount=amount
      WHERE id=v_cond.order_id AND user_id=v_cond.user_id AND status='pending';
      GET DIAGNOSTICS v_rows=ROW_COUNT;
      IF v_rows<>1 THEN RAISE EXCEPTION 'Stop-Limit parent order update failed'; END IF;

      UPDATE public.conditional_orders
      SET status='triggered',execution_order_id=v_child_id,
          triggered_at=now(),last_error=NULL,updated_at=now()
      WHERE id=v_cond.id AND status='pending';
      GET DIAGNOSTICS v_rows=ROW_COUNT;
      IF v_rows<>1 THEN RAISE EXCEPTION 'Stop-Limit trigger state update failed'; END IF;

      PERFORM pg_catalog.set_config('request.jwt.claim.sub','',true);
      PERFORM pg_catalog.set_config('request.jwt.claims','',true);
      v_processed:=v_processed+1;
      v_triggered:=v_triggered+1;
    EXCEPTION WHEN OTHERS THEN
      PERFORM pg_catalog.set_config('request.jwt.claim.sub','',true);
      PERFORM pg_catalog.set_config('request.jwt.claims','',true);
      UPDATE public.conditional_orders
      SET attempt_count=attempt_count+1,last_error=left(SQLERRM,500),updated_at=now()
      WHERE id=v_cond.id
      RETURNING attempt_count INTO v_attempt;

      IF v_attempt>=10 THEN
        SELECT * INTO v_res
        FROM public.order_reservations
        WHERE order_id=v_cond.order_id AND user_id=v_cond.user_id
        FOR UPDATE;
        IF FOUND AND v_res.status='reserved'
           AND v_res.consumed_amount>=0
           AND v_res.consumed_amount+v_res.released_amount<=v_res.reserved_amount THEN
          UPDATE public.order_reservations
          SET released_amount=reserved_amount-consumed_amount,
              status='released',updated_at=now()
          WHERE id=v_res.id;
        END IF;
        UPDATE public.orders
        SET status='rejected',remaining_amount=amount-filled_amount
        WHERE id=v_cond.order_id AND user_id=v_cond.user_id AND status='pending';
        UPDATE public.conditional_orders
        SET status='rejected',updated_at=now()
        WHERE id=v_cond.id AND status='pending';
        v_rejected:=v_rejected+1;
      ELSE
        v_skipped:=v_skipped+1;
      END IF;
    END;
  END LOOP;

  RETURN jsonb_build_object('success',true,'processed',v_processed,
    'triggered',v_triggered,'synced',v_synced,'rejected',v_rejected,'skipped',v_skipped);
END;
$function$

CREATE OR REPLACE FUNCTION public.reactivate_my_account()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_auth_time bigint;
begin
  if v_uid is null then
    raise exception 'Authentication required';
  end if;

  v_auth_time := nullif(auth.jwt() ->> 'auth_time', '')::bigint;
  if v_auth_time is null
     or v_auth_time > extract(epoch from pg_catalog.now())::bigint
     or extract(epoch from pg_catalog.now())::bigint - v_auth_time > 300 then
    raise exception 'Recent re-authentication required to reactivate this account';
  end if;

  update public.profiles
  set is_active = true,
      deactivated_at = null
  where id = v_uid
    and is_active is false;

  if not found and not exists (
    select 1 from public.profiles p where p.id = v_uid and p.is_active is true
  ) then
    raise exception 'Account profile not found';
  end if;

  return jsonb_build_object('success', true, 'status', 'active');
end;
$function$

CREATE OR REPLACE FUNCTION public.refresh_market_prices()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  r record;
  v_map record;
  v_ticker jsonb;
  v_symbol text;
  v_price numeric;
  v_ids text;
  v_request_id bigint;
BEGIN
  IF pg_catalog.pg_try_advisory_xact_lock(742019, 13) IS NOT TRUE THEN
    RETURN;
  END IF;

  FOR r IN
    SELECT q.request_id,q.provider,h.status_code,h.content,h.timed_out,h.error_msg
    FROM private.market_price_sync_requests q
    JOIN net._http_response h ON h.id=q.request_id
  LOOP
    IF r.status_code=200 AND COALESCE(r.timed_out,false)=false AND r.content IS NOT NULL THEN
      BEGIN
        IF r.provider='CoinGecko' THEN
          FOR v_map IN
            SELECT dp.pair_symbol AS symbol,dp.base_coingecko_id AS coingecko_id
            FROM public.demo_trading_pairs dp WHERE dp.is_enabled IS TRUE
            UNION
            SELECT pg_catalog.upper(ca.symbol)||'USDT',ca.coingecko_id
            FROM public.admin_market_listings l
            JOIN public.crypto_assets ca ON ca.coingecko_id=l.coingecko_id
            WHERE ca.is_active IS TRUE
          LOOP
            v_price:=NULLIF((r.content::jsonb->v_map.coingecko_id->>'usd'),'')::numeric;
            IF v_price>0 THEN
              INSERT INTO public.market_prices(symbol,price,source,updated_at)
              VALUES(v_map.symbol,v_price,'CoinGecko',now())
              ON CONFLICT(symbol) DO UPDATE SET price=EXCLUDED.price,source=EXCLUDED.source,updated_at=EXCLUDED.updated_at;
            END IF;
          END LOOP;

        ELSIF r.provider='KuCoin' AND r.content::jsonb->>'code'='200000' THEN
          FOR v_ticker IN SELECT value FROM jsonb_array_elements(r.content::jsonb->'data'->'ticker')
          LOOP
            v_symbol:=replace(v_ticker->>'symbol','-','');
            v_price:=NULLIF(v_ticker->>'last','')::numeric;
            IF v_symbol ~ '^[A-Z0-9]{2,24}USDT$' AND v_price>0
              AND EXISTS(SELECT 1 FROM public.demo_trading_pairs dp WHERE dp.is_enabled IS TRUE AND dp.pair_symbol=v_symbol) THEN
              INSERT INTO public.market_prices(symbol,price,source,updated_at)
              VALUES(v_symbol,v_price,'KuCoin',now())
              ON CONFLICT(symbol) DO UPDATE SET price=EXCLUDED.price,source=EXCLUDED.source,updated_at=EXCLUDED.updated_at;
            END IF;
          END LOOP;

        ELSIF r.provider='Gate.io' AND jsonb_typeof(r.content::jsonb)='array' THEN
          FOR v_ticker IN SELECT value FROM jsonb_array_elements(r.content::jsonb)
          LOOP
            v_symbol:=replace(v_ticker->>'currency_pair','_','');
            v_price:=NULLIF(v_ticker->>'last','')::numeric;
            IF v_symbol ~ '^[A-Z0-9]{2,24}USDT$' AND v_price>0
              AND EXISTS(SELECT 1 FROM public.demo_trading_pairs dp WHERE dp.is_enabled IS TRUE AND dp.pair_symbol=v_symbol) THEN
              INSERT INTO public.market_prices(symbol,price,source,updated_at)
              VALUES(v_symbol,v_price,'Gate.io',now())
              ON CONFLICT(symbol) DO UPDATE SET price=EXCLUDED.price,source=EXCLUDED.source,updated_at=EXCLUDED.updated_at;
            END IF;
          END LOOP;
        END IF;
      EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'Market-price response processing failed for provider %: %',r.provider,SQLERRM;
      END;
    ELSE
      RAISE WARNING 'Market-price request failed for provider %. Status: %, Error: %',r.provider,r.status_code,r.error_msg;
    END IF;
    DELETE FROM private.market_price_sync_requests WHERE request_id=r.request_id;
  END LOOP;

  DELETE FROM private.market_price_sync_requests q
  WHERE q.queued_at < now() - interval '30 minutes'
    AND NOT EXISTS (SELECT 1 FROM net.http_request_queue nq WHERE nq.id = q.request_id)
    AND NOT EXISTS (SELECT 1 FROM net._http_response h WHERE h.id = q.request_id);

  -- Back-pressure: do not enqueue another provider batch while earlier
  -- market-price requests remain queued or tracked. This also catches
  -- orphaned queue entries created by the previous stale-row cleanup.
  IF EXISTS (
      SELECT 1 FROM net.http_request_queue nq
      WHERE nq.url LIKE 'https://api.coingecko.com/api/v3/simple/price%'
         OR nq.url = 'https://api.kucoin.com/api/v1/market/allTickers'
         OR nq.url = 'https://api.gateio.ws/api/v4/spot/tickers'
  ) OR EXISTS (
      SELECT 1 FROM private.market_price_sync_requests
  ) THEN
      RETURN;
  END IF;

  -- The overflow cron fetches all remaining IDs after this first stable batch.
  SELECT pg_catalog.string_agg(x.coingecko_id,',' ORDER BY x.coingecko_id) INTO v_ids
  FROM (
    SELECT ids.coingecko_id
    FROM (
      SELECT dp.base_coingecko_id AS coingecko_id FROM public.demo_trading_pairs dp WHERE dp.is_enabled IS TRUE
      UNION
      SELECT ca.coingecko_id FROM public.admin_market_listings l
      JOIN public.crypto_assets ca ON ca.coingecko_id=l.coingecko_id WHERE ca.is_active IS TRUE
    ) ids
    WHERE ids.coingecko_id ~ '^[a-z0-9-]+$'
    ORDER BY ids.coingecko_id
    LIMIT 515
  ) x;

  IF v_ids IS NOT NULL AND v_ids<>'' THEN
    v_request_id:=net.http_get(url:='https://api.coingecko.com/api/v3/simple/price?ids='||v_ids||'&vs_currencies=usd',timeout_milliseconds:=20000);
    INSERT INTO private.market_price_sync_requests(request_id,provider) VALUES(v_request_id,'CoinGecko') ON CONFLICT(request_id) DO NOTHING;
  END IF;

  v_request_id:=net.http_get(url:='https://api.kucoin.com/api/v1/market/allTickers',timeout_milliseconds:=15000);
  INSERT INTO private.market_price_sync_requests(request_id,provider) VALUES(v_request_id,'KuCoin') ON CONFLICT(request_id) DO NOTHING;

  v_request_id:=net.http_get(url:='https://api.gateio.ws/api/v4/spot/tickers',timeout_milliseconds:=15000);
  INSERT INTO private.market_price_sync_requests(request_id,provider) VALUES(v_request_id,'Gate.io') ON CONFLICT(request_id) DO NOTHING;
END;
$function$

CREATE OR REPLACE FUNCTION public.request_bit24_exchange_sync()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p integer; rid bigint; n integer:=0;
begin
 DELETE FROM public.bit24_exchange_sync_requests q
 WHERE q.processed_at IS NULL
   AND q.requested_at < now() - interval '30 minutes'
   AND NOT EXISTS (SELECT 1 FROM net.http_request_queue nq WHERE nq.id = q.request_id)
   AND NOT EXISTS (SELECT 1 FROM net._http_response h WHERE h.id = q.request_id);

 IF EXISTS (
   SELECT 1 FROM public.bit24_exchange_sync_requests q
   WHERE q.processed_at IS NULL
 ) THEN
   RETURN 0;
 END IF;

 for p in 1..4 loop
  select net.http_get('https://pro.bit24.cash/api/v3/markets?page='||p||'&per_page=100') into rid;
  insert into public.bit24_exchange_sync_requests(request_id) values(rid) on conflict do nothing;
  n:=n+1;
 end loop;
 return n;
end; $function$

CREATE OR REPLACE FUNCTION public.request_iran_exchange_asset_sync()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  n integer := 0;
  rid bigint;
begin
  DELETE FROM public.exchange_asset_sync_requests q
  WHERE q.processed_at IS NULL
    AND q.requested_at < now() - interval '30 minutes'
    AND NOT EXISTS (SELECT 1 FROM net.http_request_queue nq WHERE nq.id = q.request_id)
    AND NOT EXISTS (SELECT 1 FROM net._http_response h WHERE h.id = q.request_id);

  IF EXISTS (
    SELECT 1 FROM public.exchange_asset_sync_requests q
    WHERE q.processed_at IS NULL
  ) THEN
    RETURN 0;
  END IF;

  select net.http_get('https://apiv2.nobitex.ir/v2/options','{}'::jsonb,'{"Accept-Encoding":"identity","Accept":"application/json"}'::jsonb,15000) into rid;
  insert into public.exchange_asset_sync_requests(request_id,exchange) values(rid,'nobitex') on conflict do nothing; n:=n+1;
  select net.http_get('https://api.wallex.ir/v1/markets','{}'::jsonb,'{"Accept-Encoding":"identity","Accept":"application/json"}'::jsonb,15000) into rid;
  insert into public.exchange_asset_sync_requests(request_id,exchange) values(rid,'wallex') on conflict do nothing; n:=n+1;
  select net.http_get('https://api-web.tabdeal.org/r/plots/currencies/dynamic-info/','{}'::jsonb,'{"Accept-Encoding":"identity","Accept":"application/json"}'::jsonb,15000) into rid;
  insert into public.exchange_asset_sync_requests(request_id,exchange) values(rid,'tabdeal') on conflict do nothing; n:=n+1;
  select net.http_get('https://api.ompfinex.com/v2/market','{}'::jsonb,'{"Accept-Encoding":"identity","Accept":"application/json"}'::jsonb,15000) into rid;
  insert into public.exchange_asset_sync_requests(request_id,exchange) values(rid,'ompfinex') on conflict do nothing; n:=n+1;
  select net.http_get('https://api.exir.io/v2/ticker/all','{}'::jsonb,'{"Accept-Encoding":"identity","Accept":"application/json"}'::jsonb,15000) into rid;
  insert into public.exchange_asset_sync_requests(request_id,exchange) values(rid,'exir') on conflict do nothing; n:=n+1;
  select net.http_get('https://api.abantether.ir/api/v2/manager/coins','{}'::jsonb,'{"Accept-Encoding":"identity","Accept":"application/json"}'::jsonb,15000) into rid;
  insert into public.exchange_asset_sync_requests(request_id,exchange) values(rid,'abantether') on conflict do nothing; n:=n+1;

  select net.http_post(
    'https://kifpool.me/api/graphql',
    '{"operationName":"headerCoins","variables":{"search":"","offset":0,"limit":2000},"extensions":{"persistedQuery":{"version":1,"sha256Hash":"bb149e99c1d2da2ca162085286128da78a9bd3936198e47e28028e20961f6f3c"}}}'::jsonb,
    '{}'::jsonb,
    '{"Content-Type":"application/json","Accept":"application/json","Origin":"https://kifpool.me","Referer":"https://kifpool.me/markets","Accept-Encoding":"identity"}'::jsonb,
    15000
  ) into rid;
  insert into public.exchange_asset_sync_requests(request_id,exchange) values(rid,'kifpool') on conflict do nothing; n:=n+1;
  return n;
end;
$function$

CREATE OR REPLACE FUNCTION public.request_market_price_refresh()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_last timestamptz;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING errcode = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles p
    WHERE p.id = v_uid AND p.is_active IS TRUE
  ) THEN
    RAISE EXCEPTION 'Active account required' USING errcode = '42501';
  END IF;

  SELECT c.last_requested_at INTO v_last
  FROM private.market_price_refresh_control c
  WHERE c.id IS TRUE
  FOR UPDATE;

  IF v_last > now() - interval '30 seconds' THEN
    RAISE EXCEPTION 'Market refresh was requested recently; wait before trying again';
  END IF;

  UPDATE private.market_price_refresh_control
  SET last_requested_at = now()
  WHERE id IS TRUE;

  PERFORM public.refresh_market_prices();

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Market price refresh queued',
    'minimum_interval_seconds', 30
  );
END;
$function$
